import React from 'react';

function JobList({ jobs, onDeleteJob }) {
  return (
    <div>
      <h2>Job List</h2>
      {jobs.length === 0 ? (
        <p>No jobs available. Please add a job using the form above.</p>
      ) : (
        <ul>
          {jobs.map((job) => (
            <li key={job.id}>
              <strong>{job.title}</strong> at {job.company} - ${job.salary.toLocaleString()} ({job.sector})
              <button onClick={() => onDeleteJob(job.id)} style={{ marginLeft: '10px', color: 'red', cursor: 'pointer' }}>
                Delete
              </button>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}

export default JobList;
